template:
% 参数由系统自动注入：\def\radius{3} \def\anglea{30} \def\angleb{130} \def\showchord{1} \def\showaxis{1} \def\showperp{0} \def\showequalmark{0} \def\showmidpoint{0} \def\showradii{0} \def\showrotation{0} \def\showcentralsym{0} \def\showcenter{1} \def\labela{A} \def\labelb{B} \def\labelc{C} \def\labelm{M}
% 视觉归一化：把圆直径缩放到 6cm，保证图形视觉大小稳定。
\pgfmathsetmacro{\figscale}{3 / \radius}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
% A、B 在圆上；关于角平分方向 (anglea+angleb)/2 的那条直径镜像对称（镜像把角 t 映成 anglea+angleb-t，正好 A<->B）
\pgfmathsetmacro{\Ax}{\radius*cos(\anglea)}
\pgfmathsetmacro{\Ay}{\radius*sin(\anglea)}
\pgfmathsetmacro{\Bx}{\radius*cos(\angleb)}
\pgfmathsetmacro{\By}{\radius*sin(\angleb)}
\pgfmathsetmacro{\axang}{(\anglea + \angleb)/2}
% M = AB 中点，必在对称轴上；C = A 关于圆心的对称点
\pgfmathsetmacro{\Mx}{(\Ax + \Bx)/2}
\pgfmathsetmacro{\My}{(\Ay + \By)/2}
\pgfmathsetmacro{\Cx}{-\Ax}
\pgfmathsetmacro{\Cy}{-\Ay}
% 半弦长 = radius*sin((angleb-anglea)/2)，约束已保证其大于 0（A 与 B 不重合）
\pgfmathsetmacro{\halfab}{\radius*sin((\angleb - \anglea)/2)}
% A->B 的单位向量（弦方向）
\pgfmathsetmacro{\vabx}{(\Bx - \Ax)/(2*\halfab)}
\pgfmathsetmacro{\vaby}{(\By - \Ay)/(2*\halfab)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (O) at (0,0);
  \coordinate (A) at (\Ax,\Ay);
  \coordinate (B) at (\Bx,\By);
  \coordinate (M) at (\Mx,\My);
  \coordinate (C) at (\Cx,\Cy);
  % 圆
  \draw[thick] (O) circle [radius=\radius];
  % 对称轴：过圆心、方向为 axang 的直径，两端各伸出一点
  \ifnum\showaxis>0
    \pgfmathsetmacro{\axl}{1.12*\radius}
    \draw[thick, dashed] ({-\axl*cos(\axang)},{-\axl*sin(\axang)}) -- ({\axl*cos(\axang)},{\axl*sin(\axang)});
  \fi
  % 弦 AB
  \ifnum\showchord>0
    \draw[thick] (A) -- (B);
  \fi
  % 半径 OA、OB
  \ifnum\showradii>0
    \draw[thick] (O) -- (A);
    \draw[thick] (O) -- (B);
  \fi
  % 中心对称：直径 AC（C 是 A 关于圆心的对称点）
  \ifnum\showcentralsym>0
    \draw[thick] (A) -- (C);
    \fill (C) circle [radius=\dotr pt];
    \node at ({1.15*\Cx},{1.15*\Cy}) {$\labelc$};
  \fi
  % 旋转角 ∠AOB 的角弧（由 anglea 逆时针扫到 angleb）
  \ifnum\showrotation>0
    \pgfmathsetmacro{\rarc}{min(0.55/\figscale, \radius*0.3)}
    \draw[thick] ({\rarc*cos(\anglea)},{\rarc*sin(\anglea)}) arc[start angle=\anglea, end angle=\angleb, radius=\rarc];
  \fi
  % 对称轴垂直于弦的直角记号（记号朝圆心一侧；M 与 O 重合时自动退化为不可见）
  \ifnum\showperp>0
    \pgfmathsetmacro{\mlen}{max(sqrt(\Mx*\Mx + \My*\My), 0.0001)}
    \pgfmathsetmacro{\wmx}{-\Mx/\mlen}
    \pgfmathsetmacro{\wmy}{-\My/\mlen}
    \pgfmathsetmacro{\rms}{min(0.24/\figscale, \radius*0.12, \halfab*0.3)}
    \draw[thick] ({\Mx+\rms*\vabx},{\My+\rms*\vaby}) -- ({\Mx+\rms*\vabx+\rms*\wmx},{\My+\rms*\vaby+\rms*\wmy}) -- ({\Mx+\rms*\wmx},{\My+\rms*\wmy});
  \fi
  % AM=MB 等长记号（垂直于弦的短划）
  \ifnum\showequalmark>0
    \pgfmathsetmacro{\tk}{min(0.16/\figscale, \halfab*0.28)}
    \pgfmathsetmacro{\qax}{(\Ax + \Mx)/2}
    \pgfmathsetmacro{\qay}{(\Ay + \My)/2}
    \pgfmathsetmacro{\qbx}{(\Bx + \Mx)/2}
    \pgfmathsetmacro{\qby}{(\By + \My)/2}
    \draw[thick] ({\qax - \tk*\vaby},{\qay + \tk*\vabx}) -- ({\qax + \tk*\vaby},{\qay - \tk*\vabx});
    \draw[thick] ({\qbx - \tk*\vaby},{\qby + \tk*\vabx}) -- ({\qbx + \tk*\vaby},{\qby - \tk*\vabx});
  \fi
  % 交点 M
  \ifnum\showmidpoint>0
    \fill (M) circle [radius=\dotr pt];
    \pgfmathsetmacro{\mlab}{atan2(\My,\Mx)}
    \node at ({\Mx + 0.17*\radius*cos(\mlab)},{\My + 0.17*\radius*sin(\mlab)}) {$\labelm$};
  \fi
  % A、B 及字母（沿半径方向外推，避免压线）
  \fill (A) circle [radius=\dotr pt];
  \node at ({1.15*\Ax},{1.15*\Ay}) {$\labela$};
  \fill (B) circle [radius=\dotr pt];
  \node at ({1.15*\Bx},{1.15*\By}) {$\labelb$};
  % 圆心 O
  \ifnum\showcenter>0
    \fill (O) circle [radius=\dotr pt];
    \node[below left=2pt] at (O) {$O$};
  \fi
\end{tikzpicture}
